export type SuiteId = 'folio' | 'forge' | 'sentinel' | 'i3d' | 'ai'

/** One published image: path under the site base, pixel width, pixel height, and whether a 640px copy exists. */
export type DialogImage = [src: string, w: number, h: number, small: 0 | 1]

/** One dialog state from the inventory, generated by scripts/build-dialogs.py. */
export interface DialogShot {
  /** Inventory row (several states of one dialog share it). */
  id: string
  title: string
  state: string
  kind: string
  /** A screenshot of the installed build; otherwise a render of the product's own window with sample data. */
  real?: 1
  dark: DialogImage
  light?: DialogImage
}

export interface Product {
  slug: string
  key: string
  name: string
  suite: SuiteId
  panel: string
  software: string[]
  /** Revit versions the shipping build targets (empty when not a Revit add-in). */
  revit: string[]
  /** The product's own one-line summary (ribbon tooltip or repository description). */
  tagline: string
  /** The product's own long description, as shipped. */
  description: string
  capabilities: string[]
  safeguards: string[]
  dialogs: DialogShot[]
  /** The everyday problem it addresses; written from the product's own description. */
  problem?: string
  /** Interactive demo id, when one exists. */
  demo?: string
  /** Extra media published by the product itself (screenshots, animations). */
  media?: { src: string; alt: string; kind: 'image' | 'animation' }[]
  status: 'available' | 'preview' | 'enterprise'
  platform?: string
  requirements?: string[]
}

export interface Suite {
  id: SuiteId
  name: string
  short: string
  color: string
  summary: string
  focus: string
}
